package com.northstar.crm.web;import com.northstar.crm.security.ScopeTokenService;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;@RestController@RequestMapping("/core-mock/v1")public class CoreMockController {private final ScopeTokenService tokens;private final byte[] credential;public CoreMockController(ScopeTokenService tokens,@Value("${app.core-mock-credential}")String credential){this.tokens=tokens;this.credential=credential.getBytes(StandardCharsets.UTF_8);}@PostMapping("/webhook-deliveries")public ResponseEntity<Map<String,Object>> deliver(@RequestHeader("X-Core-Credential")String supplied,@RequestHeader("X-Decision-Scope")String token,@RequestBody Map<String,String> body){if(!MessageDigest.isEqual(credential,supplied.getBytes(StandardCharsets.UTF_8)))return ResponseEntity.status(401).body(Map.of("code","CORE_AUTH_FAILED"));final UUID org;try{org=tokens.verify(token,"webhook:deliver");}catch(SecurityException e){return ResponseEntity.status(403).body(Map.of("code","CORE_SCOPE_INVALID"));}var event=Optional.ofNullable(body.get("event")).orElse("");if(event.length()>60)return ResponseEntity.badRequest().body(Map.of("code","CORE_EVENT_INVALID"));return ResponseEntity.accepted().body(Map.of("code","CORE_ACCEPTED","organization",org,"deliveryId",UUID.randomUUID()));}}
